-- Per-player-week fantasy game log (trailing two regular seasons) that
-- powers the /my-team "My Analysis" filter builder -- pick a game window
-- (season, week range, home/away, wins/losses) and the scatter recomputes
-- PPG / totals / game counts over just those games.
--
-- Replaces the pre-aggregated player_splits table (0026) -- every split it
-- offered is now computed client-side from this log, plus arbitrary
-- windows. Generated by model/player_game_log.R, published via
-- web/scripts/publish-player-game-log.mjs. Public read, no tier gate.

drop table if exists public.player_splits;

create table public.player_game_log (
  normalized_name    text not null,   -- join key (see portfolio.js normalizePlayerName)
  player_name        text not null,
  position           text,
  season             int  not null,
  week               int  not null,
  team               text,
  opponent           text,
  is_home            boolean,
  won                boolean,
  fantasy_points_ppr numeric,
  receptions         numeric,
  targets            numeric,
  rec_yards          numeric,
  rush_yards         numeric,
  rush_att           numeric,
  pass_yards         numeric,
  tds                numeric,
  primary key (player_name, season, week)
);

create index player_game_log_normalized_name_idx
  on public.player_game_log (normalized_name);

alter table public.player_game_log enable row level security;

create policy "Anyone can read the player game log"
  on public.player_game_log for select
  using (true);
